const PREFIX = 'ville-du-bien-etre:';
const CACHE = PREFIX + VERSION;
const SCOPE = new URL(self.registration.scope);
const ASSETS = ["index.html","app.js","styles.css","styles-activities.css","styles-features.css","manifest.webmanifest","icons/apple-touch-icon.png","icons/favicon-32.png","icons/icon-192.png","icons/icon-512.png","icons/icon-maskable-512.png","fonts/figtree-latin-ext.woff2","fonts/figtree-latin.woff2","fonts/young-serif-latin-ext.woff2","fonts/young-serif-latin.woff2"].map(p => new URL(p, SCOPE).href);
